//! The generated "Template functions" reference page (`cargo run -p xtask -- gen-docs`).

use std::fmt::Write as _;

use crate::funcs::{Kind, CATALOGUE};

pub const REFERENCE_DOC_PATH: &str = "site/src/content/docs/docs/reference/template-functions.md";

fn cell(s: &str) -> String {
    s.replace('|', "\\|")
}

pub fn reference_markdown() -> String {
    let mut out = String::from(
        "---\ntitle: Template functions\ndescription: Every function and filter available in snippet templates, with its signature and an example.\n---\n\n\
         <!-- Generated by `cargo run -p xtask -- gen-docs` from `mt_snippets::funcs::CATALOGUE`. Do not edit. -->\n\n\
         How templates work: [Snippets](/docs/snippets/). Templates run only when `snippets.templates = true`.\n\n\
         Arguments in `[…]` are optional. `n`/`len` arguments are capped at 4096. Every function accepts `default=VALUE`, \
         which replaces a runtime failure with VALUE. System functions always describe the **local** machine, even in an \
         SSH pane. No function spawns a process or touches the network.\n",
    );
    for (title, kind) in [("Functions", Kind::Func), ("Filters", Kind::Filter)] {
        let _ = write!(out, "\n## {title}\n");
        let mut groups: Vec<&str> = Vec::new();
        for d in CATALOGUE.iter().filter(|d| d.kind == kind) {
            if !groups.contains(&d.group) {
                groups.push(d.group);
            }
        }
        for g in groups {
            let _ = write!(
                out,
                "\n### {g}\n\n| Signature | Description | Example |\n|---|---|---|\n"
            );
            for d in CATALOGUE.iter().filter(|d| d.kind == kind && d.group == g) {
                let sig = if kind == Kind::Filter {
                    format!("… \\| {}", cell(d.sig))
                } else {
                    cell(d.sig)
                };
                let _ = writeln!(
                    out,
                    "| `{sig}` | {} | `{}` |",
                    cell(d.desc),
                    cell(d.example)
                );
            }
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_catalogue_entry_is_listed_once() {
        let md = reference_markdown();
        for d in CATALOGUE {
            assert!(md.contains(&cell(d.sig)), "{}", d.name);
        }
        assert!(md.starts_with("---\ntitle: Template functions"));
        assert!(md.contains("### Generators") && md.contains("### Paths"));
    }
}
